drop policy if exists enterprise_documents_storage_read on storage.objects;create policy enterprise_documents_storage_read on storage.objects for select to authenticated using(bucket_id='enterprise-documents'and private.document_can_read((storage.foldername(name))[1]::uuid));
drop policy if exists enterprise_documents_storage_write on storage.objects;create policy enterprise_documents_storage_write on storage.objects for insert to authenticated with check(bucket_id='enterprise-documents'and private.document_can_write((storage.foldername(name))[1]::uuid));
do $$declare t text;begin foreach t in array array['documents','document_versions','document_links','document_reviews','signature_requests','document_comments','document_events']loop if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime'and schemaname='public'and tablename=t)then execute format('alter publication supabase_realtime add table public.%I',t);end if;end loop;end$$;
commit;
